questionvariables.text:
stack_include("contribl://prooflib.mac");
proof_steps: [
  ["defn",    "Let \\(P(n)\\) be the statement \\(2^n > n\\)."],
  ["base",    "When \\(n = 1\\), \\(2^1 = 2 > 1\\), so \\(P(1)\\) is true."],
  ["hyp",     "Assume that \\(P(k)\\) is true for some positive integer \\(k\\), that is, \\(2^k > k\\)."],
  ["s1",      "Then \\(2^{k+1} = 2 \\times 2^k\\)"],
  ["s2",      "\\(> 2k\\), by the induction hypothesis,"],
  ["s3",      "\\(\\geq k + 1\\), because \\(k \\geq 1\\)."],
  ["sc",      "So \\(2^{k+1} > k + 1\\), which means that \\(P(k+1)\\) is true."],
  ["conc",    "\\(P(1)\\) is true, and \\(P(k)\\) implies \\(P(k+1)\\) for every positive integer \\(k\\), so by the principle of mathematical induction \\(P(n)\\) is true for every positive integer \\(n\\)."],
  ["d_all",   "Assume that \\(2^n > n\\) for every positive integer \\(n\\)."],
  ["d_check", "Since \\(2 > 1\\), \\(4 > 2\\) and \\(8 > 3\\), \\(P(n)\\) is true for every positive integer \\(n\\)."]
];
proof_steps: random_permutation(proof_steps);
ta: proof_ind("defn", proof("base"), proof("hyp", "s1", "s2", "s3", "sc"), "conc");

feedbackvariables.text:
sa: parsons_decode(ans1);
sal: args(proof_flatten(sa));
[pd, saa]: proof_assessment(sa, proof_alternatives(ta));
has_all: if member("d_all", sal) then 1 else 0;
has_check: if member("d_check", sal) then 1 else 0;
